// Build calendar payload from Supabase response
const appt = $input.first().json[0];
if (!appt) { throw new Error('Appointment not found'); }

const client = appt.profiles || {};
const services = (appt.appointment_services || []).map(s => s.services?.name).filter(Boolean);
const serviceNames = services.join(', ') || 'Servicio LAP';

// Build RFC3339 datetimes in Panama timezone
const dateStr = appt.appointment_date; // YYYY-MM-DD
const startDT = `${dateStr}T${appt.start_time}`; // YYYY-MM-DDTHH:MM:SS
const endDT = `${dateStr}T${appt.end_time}`;

// Build ICS-formatted datetimes (for fallback)
const toIcsDT = (d, t) => `${d.replace(/-/g,'')}T${t.replace(/:/g,'').slice(0,6)}`;
const icsStart = toIcsDT(dateStr, appt.start_time);
const icsEnd = toIcsDT(dateStr, appt.end_time);

// Manual Gcal template URL (always included as fallback link)
const encode = encodeURIComponent;
const gcalUrl = `https://calendar.google.com/calendar/render?action=TEMPLATE` +
  `&text=${encode('Servicio LAP: ' + serviceNames)}` +
  `&dates=${icsStart}/${icsEnd}` +
  `&location=${encode(appt.location_address || '')}` +
  `&details=${encode('Cita confirmada con LAP Services Panama.')}`;

return {
  appointment_id: appt.id,
  client_name: client.name || 'Cliente',
  client_email: client.email,
  client_phone: client.phone,
  date: dateStr,
  start_time: appt.start_time,
  end_time: appt.end_time,
  start_dt: startDT,
  end_dt: endDT,
  ics_start: icsStart,
  ics_end: icsEnd,
  location: appt.location_address || '',
  notes: appt.notes || '',
  service_names: serviceNames,
  summary: `Servicio LAP: ${serviceNames} - ${client.name || ''}`.trim(),
  description: `Servicios: ${serviceNames}\n\nCliente: ${client.name}\nTelefono: ${client.phone || 'n/a'}\n\nNotas: ${appt.notes || 'Ninguna'}\n\nVer cita: https://lapservicepty.com/admin/citas/${appt.id}`,
  gcal_template_url: gcalUrl
};

// Generate ICS content as fallback when Google Calendar fails
const p = $('Build Payload').item.json;
const pad = n => String(n).padStart(2,'0');
const now = new Date();
const dtstamp = `${now.getUTCFullYear()}${pad(now.getUTCMonth()+1)}${pad(now.getUTCDate())}T${pad(now.getUTCHours())}${pad(now.getUTCMinutes())}${pad(now.getUTCSeconds())}Z`;

const ics = [
  'BEGIN:VCALENDAR',
  'VERSION:2.0',
  'PRODID:-//LAP Services//Panama//ES',
  'CALSCALE:GREGORIAN',
  'METHOD:PUBLISH',
  'BEGIN:VEVENT',
  `UID:${p.appointment_id}@lapservicepty.com`,
  `DTSTAMP:${dtstamp}`,
  `DTSTART;TZID=America/Panama:${p.ics_start}`,
  `DTEND;TZID=America/Panama:${p.ics_end}`,
  `SUMMARY:${p.summary}`,
  `LOCATION:${p.location.replace(/,/g,'\\,')}`,
  `DESCRIPTION:${p.description.replace(/\n/g,'\\n').replace(/,/g,'\\,')}`,
  'STATUS:CONFIRMED',
  'END:VEVENT',
  'END:VCALENDAR'
].join('\r\n');

return {
  ...p,
  ics_content: ics,
  ics_filename: `LAP-cita-${p.appointment_id}.ics`,
  ics_base64: Buffer.from(ics, 'utf-8').toString('base64')
};

// Build unified email payload for both branches.
// Determines if we came from the synced or fallback path.
const payload = $('Build Payload').item.json;
// Check if ICS was generated (fallback path)
let ics = null;
try {
  ics = $('Generate ICS fallback').item.json;
} catch (e) { ics = null; }

const isFallback = !!(ics && ics.ics_content);
const fecha = new Date(payload.date + 'T12:00:00').toLocaleDateString('es-PA', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' });
const hora = payload.start_time.slice(0,5);

const subject = `Tu cita con LAP esta confirmada - ${fecha}`;

const html = `
<div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto; color: #1B5E20;">
  <div style="background: linear-gradient(135deg, #2E7D32, #4CAF50); padding: 24px; text-align: center; color: white;">
    <h1 style="margin:0">LAP Services Panama</h1>
    <p style="margin:8px 0 0">Tu cita esta confirmada</p>
  </div>
  <div style="padding: 24px; background: #f7faf7;">
    <p>Hola <b>${payload.client_name}</b>,</p>
    <p>Hemos confirmado tu cita con los siguientes detalles:</p>
    <table style="width:100%; border-collapse: collapse; margin: 16px 0;">
      <tr><td style="padding:8px; border-bottom: 1px solid #e0e0e0;"><b>Servicios</b></td><td style="padding:8px; border-bottom: 1px solid #e0e0e0;">${payload.service_names}</td></tr>
      <tr><td style="padding:8px; border-bottom: 1px solid #e0e0e0;"><b>Fecha</b></td><td style="padding:8px; border-bottom: 1px solid #e0e0e0;">${fecha}</td></tr>
      <tr><td style="padding:8px; border-bottom: 1px solid #e0e0e0;"><b>Hora</b></td><td style="padding:8px; border-bottom: 1px solid #e0e0e0;">${hora}</td></tr>
      <tr><td style="padding:8px;"><b>Direccion</b></td><td style="padding:8px;">${payload.location}</td></tr>
    </table>
    ${isFallback 
      ? `<p><b>Adjuntamos un archivo .ics</b> que puedes abrir para agregar el evento a tu calendario (Google Calendar, Apple Calendar, Outlook, etc.).</p>`
      : `<p>Ya te enviamos la invitacion directamente a tu Google Calendar. Revisa tu bandeja de entrada.</p>`}
    <p style="text-align:center; margin: 24px 0;">
      <a href="${payload.gcal_template_url}" style="background:#2E7D32; color:white; padding:12px 24px; text-decoration:none; border-radius:8px; display:inline-block;">Agregar a Google Calendar</a>
    </p>
    <p style="font-size:12px; color:#666;">Si tienes preguntas, respondenos o escribenos por WhatsApp al +507 6984-1395.</p>
  </div>
</div>`;

return {
  ...payload,
  subject,
  html,
  is_fallback: isFallback,
  attach_ics: isFallback,
  ics_content: ics?.ics_content,
  ics_filename: ics?.ics_filename,
  ics_base64: ics?.ics_base64
};
